(ns armstrong-numbers) (defn digits [n] (if (pos? n) (conj (digits (quot n 10)) (mod n 10)) [])) (defn expt [x y] (if (zero? y) 1 (* x (expt x (dec y))))) (defn sum-of-digits [n] (let [ds (digits n) num-of-digs (count ds)] (apply + (map #(expt % num-of-digs) ds)))) (defn armstrong? [n] (= n (sum-of-digits n)))
